CREATE OR REPLACE FUNCTION app.upsert_section_def_version(p_slug text, p_name text, p_category text, p_source_html text, p_source_css text, p_compiled_css text, p_compiled_ast jsonb, p_slots jsonb, p_render_hash text, p_sanitizer_policy_version integer, p_css_policy_version integer, p_changelog text, p_carries_trusted_code boolean, p_definition_kind text, p_structured_doc jsonb, p_structured_schema_version integer, p_scope text, p_site_id uuid)
 RETURNS TABLE(section_def_id uuid, version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE placement text;
BEGIN
  -- Same lock as the editor CAS command: the approved predecessor cannot
  -- change between the visual check and the immutable insert.
  PERFORM pg_advisory_xact_lock(hashtextextended('section-authoring:'||COALESCE(p_slug,''),55));
