  PERFORM app.check_section_authoring(p_slug,p_site_id,p_scope,p_definition_kind,p_source_html,p_source_css,p_compiled_css,
    p_compiled_ast,p_slots,p_structured_doc,COALESCE(p_carries_trusted_code,false),COALESCE(placement,'page'));
  RETURN QUERY SELECT * FROM app.upsert_section_def_version_before_visual_roles(
    p_slug,p_name,p_category,p_source_html,p_source_css,p_compiled_css,p_compiled_ast,p_slots,p_render_hash,
    p_sanitizer_policy_version,p_css_policy_version,p_changelog,p_carries_trusted_code,p_definition_kind,
